const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
test({ sr: 'poziva fn samo jednom posle pauze', en: 'calls fn only once after the pause' }, async () => {
  let calls = 0;
  const d = debounce(() => { calls++; }, 30);
  d(); d(); d();
  await wait(90);
  expect(calls).toBe(1);
});
test({ sr: 'ne poziva fn pre isteka vremena', en: 'does not call fn before the delay' }, async () => {
  let calls = 0;
  const d = debounce(() => { calls++; }, 60);
  d();
  await wait(10);
  expect(calls).toBe(0);
  await wait(90);
});

