test('passes the arguments of the last call', async () => {
  let got;
  const d = debounce((x) => { got = x; }, 20);
  d(1); d(2); d(3);
  await wait(80);
  expect(got).toBe(3);
});
test('every call restarts the timer', async () => {
  let calls = 0;
  const d = debounce(() => { calls++; }, 60);
  d();
  await wait(35);
  d();
  await wait(35);
  expect(calls).toBe(0);
  await wait(90);
  expect(calls).toBe(1);
});

solutions.code:
function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}
